"use strict";

const fs = require("fs");
const Typesense = require("typesense");

const API_KEY_FILE = "/etc/typesense-api-key";

function readApiKey() {
  // Allow overriding via env var for local development/testing, but default
  // to reading the key from the well-known file used during verification.
  if (process.env.TYPESENSE_API_KEY) {
    return process.env.TYPESENSE_API_KEY;
  }
  return fs.readFileSync(API_KEY_FILE, "utf8").trim();
}

function createClient() {
  const host = process.env.TYPESENSE_HOST || "127.0.0.1";
  const port = Number(process.env.TYPESENSE_PORT || 8108);
  const protocol = process.env.TYPESENSE_PROTOCOL || "http";
  const apiKey = readApiKey();

  return new Typesense.Client({
    nodes: [{ host, port, protocol }],
    apiKey,
    connectionTimeoutSeconds: 10,
  });
}

module.exports = { createClient };

"use strict";

const COLLECTION_NAME = "catalog";

const COLLECTION_SCHEMA = {
  name: COLLECTION_NAME,
  fields: [
    { name: "name_en", type: "string", locale: "en", stem: true },
    { name: "name_fr", type: "string", locale: "fr", stem: true },
    { name: "name_de", type: "string", locale: "de", stem: true },
  ],
};

module.exports = { COLLECTION_NAME, COLLECTION_SCHEMA };

"use strict";

const fs = require("fs");
const path = require("path");
const { COLLECTION_NAME, COLLECTION_SCHEMA } = require("./schema");

const DATA_FILE = path.join(__dirname, "..", "data", "catalog.json");

async function ensureCollection(client) {
  try {
    await client.collections(COLLECTION_NAME).retrieve();
  } catch (err) {
    if (err && err.httpStatus === 404) {
      await client.collections().create(COLLECTION_SCHEMA);
    } else {
      throw err;
    }
  }
}

function loadCatalogData() {
  const raw = fs.readFileSync(DATA_FILE, "utf8");
  const records = JSON.parse(raw);
  if (!Array.isArray(records)) {
    throw new Error(`Expected ${DATA_FILE} to contain a JSON array`);
  }
  return records;
}

async function indexCatalog(client) {
  await ensureCollection(client);
  const records = loadCatalogData();
  if (records.length === 0) {
    return { imported: 0 };
  }
  // Upsert is idempotent: re-running on every startup will not create
  // duplicates and will keep the index in sync with the seed data.
  await client
    .collections(COLLECTION_NAME)
    .documents()
    .import(records, { action: "upsert" });
  return { imported: records.length };
}

module.exports = { ensureCollection, loadCatalogData, indexCatalog, DATA_FILE };

"use strict";

const { COLLECTION_NAME } = require("./schema");

const SUPPORTED_LANGS = new Set(["en", "fr", "de"]);
const DEFAULT_LANG = "en";

function normalizeLang(lang) {
  if (typeof lang === "string" && SUPPORTED_LANGS.has(lang)) {
    return lang;
  }
  return DEFAULT_LANG;
}

async function searchCatalog(client, rawQuery, rawLang) {
  const lang = normalizeLang(rawLang);
  const query = typeof rawQuery === "string" ? rawQuery.trim() : "";

  if (query === "") {
    return { hits: [] };
  }

  const nameField = `name_${lang}`;

  const results = await client
    .collections(COLLECTION_NAME)
    .documents()
    .search({
      q: query,
      query_by: nameField,
    });

  const hits = (results.hits || []).map((hit) => ({
    id: hit.document.id,
    name: hit.document[nameField],
  }));

  return { hits };
}

module.exports = { searchCatalog, normalizeLang, SUPPORTED_LANGS, DEFAULT_LANG };

"use strict";

const path = require("path");
const express = require("express");

const { createClient } = require("./typesenseClient");
const { indexCatalog } = require("./indexer");
const { searchCatalog } = require("./search");

const PORT = Number(process.env.PORT || 3000);
const HOST = process.env.HOST || "0.0.0.0";

function createApp(client) {
  const app = express();

  app.use(express.static(path.join(__dirname, "..", "public")));

  app.get("/api/search", async (req, res) => {
    try {
      const { q, lang } = req.query;
      const result = await searchCatalog(client, q, lang);
      res.status(200).json(result);
    } catch (err) {
      console.error("Search failed:", err);
      res.status(500).json({ hits: [], error: "search_failed" });
    }
  });

  return app;
}

async function main() {
  const client = createClient();

  console.log("Ensuring Typesense collection exists and is indexed...");
  const { imported } = await indexCatalog(client);
  console.log(`Indexed ${imported} catalog record(s).`);

  const app = createApp(client);
  app.listen(PORT, HOST, () => {
    console.log(`Catalog search server listening on http://${HOST}:${PORT}`);
  });
}

if (require.main === module) {
  main().catch((err) => {
    console.error("Fatal error during startup:", err);
    process.exit(1);
  });
}

module.exports = { createApp, main };

